head.script:
// 테스트 설명, 유효성 값 설정
//  _3 : Body 가 MultiLine 인 구성에서 columnInfo 파라미터의 Column 인덱스 고유성을 검증하는 분리 샘플
//       (_1 은 Column 인덱스 지정, _2 는 Column ID 지정 / 공통 유효성은 _1, _2 에서 검증)
scwin.tData = {
    "description" : "[gridView > M > setIgnoreChar]<br/>Body Column 정보를 사용하여 특정 Column 의 ignoreChar 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄) 이며 한 데이터 Row 가 2줄에 걸쳐 표시됩니다. 두 줄에 나뉜 Column 이지만 인덱스는 이어져 부여됩니다 (1줄 col1=0 / col2=1, 2줄 col3=2 / col4=3). 4개 Column 모두 inputType=text.\n[절차] columnInfo / ignoreChar 선택 -> setIgnoreChar 실행 -> 지정한 Column 의 셀을 더블클릭해 입력 불가 문자를 섞어 입력한 뒤 Enter 또는 다른 셀 클릭으로 확정 (onafteredit 로 확정값 출력).\n[확인] setIgnoreChar 는 기존 셀 데이터를 바꾸지 않고 편집 입력에만 적용됩니다. 2줄에 있는 Column 도 인덱스 2, 3 으로 지정되어 위/아래 줄의 Column 이 각각 구분 적용되는지 확인합니다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (영문 대소문자 + 숫자 + 특수문자 혼합 -> 편집 시 ignoreChar 필터 결과가 드러나도록)
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성한다.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "Ab1-2c", "col2": "Hi12!x", "col3": "9a8B7c", "col4": "X9-y8Z" },
        { "col1": "Zz9_8x", "col2": "Wo34?y", "col3": "1q2W3e", "col4": "Q1-w2R" }
    ]);

    // target 생성
    //  ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //   1줄 : col1(인덱스 0) / col2(인덱스 1)
    //   2줄 : col3(인덱스 2) / col4(인덱스 3)
    //   -> 줄이 나뉘어도 Column 인덱스는 0~3 으로 고유하게 부여된다.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" ev:onafteredit="scwin.target1_onafteredit" id="" style="width:560px;height:260px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="1줄 - 0 : col1 (text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="1줄 - 1 : col2 (text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="2줄 - 2 : col3 (text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="2줄 - 3 : col4 (text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setIgnoreChar 실행 : Body 가 MultiLine 이어도 Column 인덱스는 줄에 걸쳐 고유하므로
//  지정한 인덱스가 어느 줄의 어떤 Column 으로 해석되었는지 Column ID 와 반영된 ignoreChar 를 함께 출력한다.
//  (쌍이 되는 get 메소드가 없어 getCellInfo 의 options.ignoreChar 로 반영값을 확인한다.)
scwin.btn_setIgnoreChar_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let ignoreChar = par_ignoreChar.getValue();

    scwin.target1.setIgnoreChar(columnInfo, ignoreChar);
    let colID = scwin.target1.getColumnID(columnInfo);
    let applied = scwin.target1.getCellInfo(columnInfo).options.ignoreChar;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setIgnoreChar(" + columnInfo + ", '" + ignoreChar + "') -> 적용 Column ID : " + colID
        + " (" + (columnInfo < 2 ? "1줄" : "2줄") + "), 설정된 ignoreChar : '" + applied + "'");
}



// 셀 편집 종료 시 발생 : 편집 중 입력한 문자에 ignoreChar 규칙이 적용된 확정값을 출력
//  MultiLine 이므로 같은 rowIndex 라도 columnIndex(0~3) 로 위/아래 줄의 Column 이 구분된다.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit | Row " + rowIndex + " / Column 인덱스 " + columnIndex + " 편집 확정값 : '" + value + "'");
}
